<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireAuth();$pdo=$db->getConnection();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$stmt=$pdo->prepare("INSERT INTO customer_feedback (user_id,feedback_type,subject,message,rating,status,created_at) VALUES (?,?,?,?,?,'new',NOW())");$stmt->execute([$auth->getUserId(),$_POST['feedback_type']??'general',trim($_POST['subject']??''),trim($_POST['message']??''),max(1,min(5,(int)($_POST['rating']??5)))]);$msg='Thank you for your feedback.';}catch(Throwable $e){$msg='Feedback could not be saved.';}}$rows=[];try{$stmt=$pdo->prepare("SELECT * FROM customer_feedback WHERE user_id=? ORDER BY created_at DESC LIMIT 20");$stmt->execute([$auth->getUserId()]);$rows=$stmt->fetchAll();}catch(Throwable $e){}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customer Feedback</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5" style="max-width:850px"><h2>Customer Feedback</h2><?php if($msg):?><div class="alert alert-info"><?=htmlspecialchars($msg)?></div><?php endif;?><div class="card mb-4"><div class="card-body"><form method="post"><select class="form-select mb-2" name="feedback_type"><option value="general">General</option><option value="baggage">Baggage</option><option value="service">Service</option></select><input class="form-control mb-2" name="subject" placeholder="Subject" required><textarea class="form-control mb-2" name="message" placeholder="Message" required></textarea><select class="form-select mb-3" name="rating"><?php for($i=5;$i>=1;$i--):?><option value="<?=$i?>"><?=$i?> / 5</option><?php endfor;?></select><button class="btn btn-primary">Submit feedback</button></form></div></div><?php if($rows):?><div class="card"><div class="card-header">Your feedback</div><ul class="list-group list-group-flush"><?php foreach($rows as $r):?><li class="list-group-item"><strong><?=htmlspecialchars($r['subject'])?></strong> · <?=htmlspecialchars($r['status'])?> · <?=intval($r['rating'])?>/5<br><?=htmlspecialchars($r['message'])?></li><?php endforeach;?></ul></div><?php endif;?></div></body></html>